  "GetWhoStrikesFirst": {
    returnType: "u8",
    params: "u8 battler1, u8 battler2, bool8 ignoreChosenMoves",
    callsTo: ["FlagGet","GetBattlerSide","GetItemHoldEffect","GetItemHoldEffectParam","Random"],
    lineCount: 126,
    bodyC: "u8 strikesFirst = 0;\n    u8 speedMultiplierBattler1 = 0, speedMultiplierBattler2 = 0;\n    u32 speedBattler1 = 0, speedBattler2 = 0;\n    u8 holdEffect = 0;\n    u8 holdEffectParam = 0;\n    u16 moveBattler1 = 0, moveBattler2 = 0;\n\n    if (WEATHER_HAS_EFFECT)\n    {\n        if ((gBattleMons[battler1].ability == ABILITY_SWIFT_SWIM && gBattleWeather & B_WEATHER_RAIN)\n            || (gBattleMons[battler1].ability == ABILITY_CHLOROPHYLL && gBattleWeather & B_WEATHER_SUN))\n            speedMultiplierBattler1 = 2;\n        else\n            speedMultiplierBattler1 = 1;\n\n        if ((gBattleMons[battler2].ability == ABILITY_SWIFT_SWIM && gBattleWeather & B_WEATHER_RAIN)\n            || (gBattleMons[battler2].ability == ABILITY_CHLOROPHYLL && gBattleWeather & B_WEATHER_SUN))\n            speedMultiplierBattler2 = 2;\n        else\n            speedMultiplierBattler2 = 1;\n    }\n    else\n    {\n        speedMultiplierBattler1 = 1;\n        speedMultiplierBattler2 = 1;\n    }\n\n    speedBattler1 = (gBattleMons[battler1].speed * speedMultiplierBattler1)\n                * (gStatStageRatios[gBattleMons[battler1].statStages[STAT_SPEED]][0])\n                / (gStatStageRatios[gBattleMons[battler1].statStages[STAT_SPEED]][1]);\n\n    if (gBattleMons[battler1].item == ITEM_ENIGMA_BERRY)\n    {\n        holdEffect = gEnigmaBerries[battler1].holdEffect;\n        holdEffectParam = gEnigmaBerries[battler1].holdEffectParam;\n    }\n    else\n    {\n        holdEffect = GetItemHoldEffect(gBattleMons[battler1].item);\n        holdEffectParam = GetItemHoldEffectParam(gBattleMons[battler1].item);\n    }\n\n     \n    if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_RECORDED_LINK | BATTLE_TYPE_FRONTIER))\n        && FlagGet(FLAG_BADGE03_GET)\n        && GetBattlerSide(battler1) == B_SIDE_PLAYER)\n    {\n        speedBattler1 = (speedBattler1 * 110) / 100;\n    }\n\n    if (holdEffect == HOLD_EFFECT_MACHO_BRACE)\n        speedBattler1 /= 2;\n\n    if (gBattleMons[battler1].status1 & STATUS1_PARALYSIS)\n        speedBattler1 /= 4;\n\n    if (holdEffect == HOLD_EFFECT_QUICK_CLAW && gRandomTurnNumber < (0xFFFF * holdEffectParam) / 100)\n        speedBattler1 = UINT_MAX;\n\n     \n\n    speedBattler2 = (gBattleMons[battler2].speed * speedMultiplierBattler2)\n                * (gStatStageRatios[gBattleMons[battler2].statStages[STAT_SPEED]][0])\n                / (gStatStageRatios[gBattleMons[battler2].statStages[STAT_SPEED]][1]);\n\n    if (gBattleMons[battler2].item == ITEM_ENIGMA_BERRY)\n    {\n        holdEffect = gEnigmaBerries[battler2].holdEffect;\n        holdEffectParam = gEnigmaBerries[battler2].holdEffectParam;\n    }\n    else\n    {\n        holdEffect = GetItemHoldEffect(gBattleMons[battler2].item);\n        holdEffectParam = GetItemHoldEffectParam(gBattleMons[battler2].item);\n    }\n\n     \n    if (!(gBattleTypeFlags & (BATTLE_TYPE_LINK | BATTLE_TYPE_RECORDED_LINK | BATTLE_TYPE_FRONTIER))\n        && FlagGet(FLAG_BADGE03_GET)\n        && GetBattlerSide(battler2) == B_SIDE_PLAYER)\n    {\n        speedBattler2 = (speedBattler2 * 110) / 100;\n    }\n\n    if (holdEffect == HOLD_EFFECT_MACHO_BRACE)\n        speedBattler2 /= 2;\n\n    if (gBattleMons[battler2].status1 & STATUS1_PARALYSIS)\n        speedBattler2 /= 4;\n\n    if (holdEffect == HOLD_EFFECT_QUICK_CLAW && gRandomTurnNumber < (0xFFFF * holdEffectParam) / 100)\n        speedBattler2 = UINT_MAX;\n\n    if (ignoreChosenMoves)\n    {\n        moveBattler1 = MOVE_NONE;\n        moveBattler2 = MOVE_NONE;\n    }\n    else\n    {\n        if (gChosenActionByBattler[battler1] == B_ACTION_USE_MOVE)\n        {\n            if (gProtectStructs[battler1].noValidMoves)\n                moveBattler1 = MOVE_STRUGGLE;\n            else\n                moveBattler1 = gBattleMons[battler1].moves[*(gBattleStruct->chosenMovePositions + battler1)];\n        }\n        else\n        {\n            moveBattler1 = MOVE_NONE;\n        }\n\n        if (gChosenActionByBattler[battler2] == B_ACTION_USE_MOVE)\n        {\n            if (gProtectStructs[battler2].noValidMoves)\n                moveBattler2 = MOVE_STRUGGLE;\n            else\n                moveBattler2 = gBattleMons[battler2].moves[*(gBattleStruct->chosenMovePositions + battler2)];\n        }\n        else\n        {\n            moveBattler2 = MOVE_NONE;\n        }\n    }\n\n     \n    if (gBattleMoves[moveBattler1].priority != 0 || gBattleMoves[moveBattler2].priority != 0)\n    {\n         \n        if (gBattleMoves[moveBattler1].priority == gBattleMoves[moveBattler2].priority)\n        {\n            if (speedBattler1 == speedBattler2 && Random() & 1)\n                strikesFirst = 2;  \n            else if (speedBattler1 < speedBattler2)\n                strikesFirst = 1;  \n\n             \n        }\n        else if (gBattleMoves[moveBattler1].priority < gBattleMoves[moveBattler2].priority)\n        {\n            strikesFirst = 1;  \n        }\n\n         \n    }\n     \n    else\n    {\n        if (speedBattler1 == speedBattler2 && Random() & 1)\n            strikesFirst = 2;  \n        else if (speedBattler1 < speedBattler2)\n            strikesFirst = 1;  \n\n         \n    }\n\n    return strikesFirst;",
  },
